from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # Maps (employee, year) -> number of leave days used
        self._used: dict[tuple[str, int], int] = {}

    def _count_leave_days(self, start: date, end: date) -> int:
        count = 0
        current = start
        while current <= end:
            if current.weekday() < 5 and current not in self.holidays:
                count += 1
            current += timedelta(days=1)
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date must not be before start date.")

        days_needed = self._count_leave_days(start, end)

        # Check remaining days for each year that the request spans.
        # Unused leave does not carry over, so we validate per-year.
        per_year: dict[int, int] = {}
        current = start
        while current <= end:
            if current.weekday() < 5 and current not in self.holidays:
                per_year[current.year] = per_year.get(current.year, 0) + 1
            current += timedelta(days=1)

        for year, needed in per_year.items():
            if self.remaining(employee, year) < needed:
                raise ValueError(
                    f"Employee {employee!r} does not have enough remaining leave in {year}."
                )

        for year, needed in per_year.items():
            key = (employee, year)
            self._used[key] = self._used.get(key, 0) + needed

        return days_needed

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get((employee, year), 0)
        return self.days_per_year - used
